#import "DYTransfer.h"
#import "DYWebDAV.h"

static void DYToast(NSString *s){ dispatch_async(dispatch_get_main_queue(),^{ UIWindow *w=UIApplication.sharedApplication.keyWindow; UIViewController *vc=w.rootViewController; while(vc.presentedViewController)vc=vc.presentedViewController; UIAlertController *a=[UIAlertController alertControllerWithTitle:@"DYYYWebDAV" message:s preferredStyle:UIAlertControllerStyleAlert]; [a addAction:[UIAlertAction actionWithTitle:@"好" style:UIAlertActionStyleDefault handler:nil]]; [vc presentViewController:a animated:YES completion:nil]; }); }
@implementation DYTransfer
+ (void)startWithShareURL:(NSString *)shareURL { DYToast(@"正在解析…"); [DYResolver resolveShareURL:shareURL completion:^(NSArray<DYMediaItem *> *items,NSString *err){ if(err){DYToast(err);return;} [self process:items index:0]; }]; }
+ (void)process:(NSArray<DYMediaItem *> *)items index:(NSUInteger)i { if(i>=items.count){DYToast(@"全部上传完成");return;} DYMediaItem *m=items[i]; NSURL *u=[NSURL URLWithString:m.url]; NSURLRequest *r=[NSURLRequest requestWithURL:u]; NSURLSessionDownloadTask *d=[[NSURLSession sharedSession] downloadTaskWithRequest:r completionHandler:^(NSURL *location,NSURLResponse *resp,NSError *err){ if(err){DYToast([NSString stringWithFormat:@"下载失败：%@",err.localizedDescription]);return;} NSString *name=[NSString stringWithFormat:@"douyin_%lu.%@",(unsigned long)i,m.extension ?: @"bin"]; NSString *ct=[m.type isEqualToString:@"image"]?@"image/jpeg":([m.type isEqualToString:@"audio"]?@"audio/mpeg":@"video/mp4"); [DYWebDAV ensureDirectoryThenUploadFile:location filename:name contentType:ct completion:^(BOOL ok,NSString *msg){ if(!ok){DYToast([NSString stringWithFormat:@"上传失败：%@",msg]);return;} [self process:items index:i+1]; }]; }]; [d resume]; }
@end
